changeSet.sql:
DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM information_schema.columns WHERE table_name = 'depots' AND column_name = 'code' ) THEN ALTER TABLE depots ADD COLUMN code VARCHAR(50); END IF; END $$;
-- Initialisation intelligente du code dépôt UPDATE depots SET code = UPPER(TRIM(description)) WHERE (code IS NULL OR code = '') AND description IS NOT NULL AND LENGTH(TRIM(description)) <= 10;
UPDATE depots SET code = 'TAC' WHERE (code IS NULL OR code = '') AND nom ILIKE '%TACHAROUK%';
UPDATE depots SET code = 'BER' WHERE (code IS NULL OR code = '') AND nom ILIKE '%BERRECHID%';
UPDATE depots SET code = 'WH' WHERE (code IS NULL OR code = '') AND (nom ILIKE '%SIT%' OR nom ILIKE '%CENTRAL%' OR nom ILIKE '%PRINCIPAL%');
UPDATE depots SET code = 'DEP' WHERE (code IS NULL OR code = '');
-- Mise à jour codification BL Fournisseur (BL IN / BL Achat) -> Ex: TAC/IN/00319 UPDATE codifications_document SET prefixe = 'IN', modele_format = '{DEPOT}/{PREFIX}/{NUM}', longueur_sequence = 5, type_reinitialisation = 'CONTINUE' WHERE type_document = 'BL_FOURNISSEUR';
-- Si point de vente 5 (SIT Transmission), aligner dernier_numero au moins sur 318 UPDATE codifications_document SET dernier_numero = GREATEST(dernier_numero, 318) WHERE type_document = 'BL_FOURNISSEUR' AND point_de_vente_id = 5;
-- Mise à jour codification BL Client (BL OUT / BL Vente) -> Ex: TAC/OUT/00319 UPDATE codifications_document SET prefixe = 'OUT', modele_format = '{DEPOT}/{PREFIX}/{NUM}', longueur_sequence = 5, type_reinitialisation = 'CONTINUE' WHERE type_document = 'BL_CLIENT';
